function flattenKanaRows(rowsObj) {
  const out = [];
  for (const group of Object.values(rowsObj)) {
    for (const row of group) {
      for (const cell of row) {
        if (cell) out.push({ id: cell[0], prompt: cell[0], meaning: cell[1], reading: cell[1] });
      }
    }
  }
  return out;
}
const HIRAGANA_FLAT = flattenKanaRows(HIRAGANA_ROWS);
const KATAKANA_FLAT = flattenKanaRows(KATAKANA_ROWS);

